svg.script:
/*  */
(function() {
  var svg = document.getElementById('a12p10-svg');
  if (!svg) return;

  var btnCues = document.getElementById('a12p10-btn-cues');
  var btnNoCues = document.getElementById('a12p10-btn-nocues');
  var hsEspinha = document.getElementById('a12p10-hs-espinha');
  var hsTuberosidade = document.getElementById('a12p10-hs-tuberosidade');

  function setScene(scene) {
    svg.setAttribute('data-scene', scene);
    if (scene === 'cues') {
      btnCues.setAttribute('aria-pressed', 'true');
      btnNoCues.setAttribute('aria-pressed', 'false');
    } else {
      btnCues.setAttribute('aria-pressed', 'false');
      btnNoCues.setAttribute('aria-pressed', 'true');
    }
  }

  function setActiveTarget(target) {
    svg.setAttribute('data-active-target', target);
    if (target === 'espinha') {
      hsEspinha.setAttribute('aria-selected', 'true');
      hsTuberosidade.setAttribute('aria-selected', 'false');
    } else {
      hsEspinha.setAttribute('aria-selected', 'false');
      hsTuberosidade.setAttribute('aria-selected', 'true');
    }
  }

  if (btnCues) {
    btnCues.addEventListener('click', function() { setScene('cues'); });
    btnCues.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setScene('cues'); }
    });
  }

  if (btnNoCues) {
    btnNoCues.addEventListener('click', function() { setScene('nocues'); });
    btnNoCues.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setScene('nocues'); }
    });
  }

  if (hsEspinha) {
    hsEspinha.addEventListener('click', function() { setActiveTarget('espinha'); });
    hsEspinha.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setActiveTarget('espinha'); }
    });
  }

  if (hsTuberosidade) {
    hsTuberosidade.addEventListener('click', function() { setActiveTarget('tuberosidade'); });
    hsTuberosidade.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setActiveTarget('tuberosidade'); }
    });
  }
})();
/*  */
